* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  padding: 50px;
  font-family: 'Open Sans', sans-serif;
}

h2 {
  line-height: calc(100vw / 50 + 0.3rem);
  font-size: calc(100vw / 50);
  font-weight: 800;
  text-align: center;
  text-transform: uppercase;

  /* Код здесь */
}

.parent {
  width: 100%;
}

.images {
  display: flex;
  justify-content: space-between;
  width: calc(3 / 5 * 100%);
  padding: 20px;
}

.content {
  width: calc(2 / 5 * 100%);
  margin-left: auto;
  padding: 20px;
}

.image,
.wildcard {
  width: calc((100% - 40px) / 3);
}

.images,
.content,
.image,
.wildcard {
  border: 1px solid #000;
}

.wildcard {
  display: flex;
  justify-content: center;
  align-items: center;
  color: #ffc802;
  font-weight: 800;
  font-size: 50px;
  background-color: #000;
}
